import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const f=JSON.parse('{"title":"Key Figures and Organizations","description":"","frontmatter":{},"headers":[],"relativePath":"en/0095-关键人物与组织.md","filePath":"en/0095-关键人物与组织.md"}'),a={name:"en/0095-关键人物与组织.md"};function r(d,t,s,h,c,l){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="key-figures-and-organizations" tabindex="-1">Key Figures and Organizations <a class="header-anchor" href="#key-figures-and-organizations" aria-label="Permalink to &quot;Key Figures and Organizations&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>95</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>key figures, important organizations, historical roles, institutional functions, symbiotic civilization</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>This document records the key figures and important organizations in the development of the Anchor Symbiotic Civilization, arranged by historical period and organizational type. The key figures section lists each figure&#39;s name, period, core contributions, and historical standing; the important organizations section lists each organization&#39;s name, founding time, core functions, and historical role. This document is a dynamically updated document; as history advances and organizations evolve, it will be continuously supplemented and revised.</p><h2 id="ii-key-figures" tabindex="-1">II. Key Figures <a class="header-anchor" href="#ii-key-figures" aria-label="Permalink to &quot;II. Key Figures&quot;">​</a></h2><h3 id="_2-1-pioneering-thinkers-of-the-pre-anchor-era" tabindex="-1">2.1 Pioneering Thinkers of the Pre-Anchor Era <a class="header-anchor" href="#_2-1-pioneering-thinkers-of-the-pre-anchor-era" aria-label="Permalink to &quot;2.1 Pioneering Thinkers of the Pre-Anchor Era&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Period</th><th>Core contributions</th><th>Historical standing</th></tr></thead><tbody><tr><td>Xuánhéng Zǐ</td><td>approx. −500 million years</td><td>The first thinker to systematically reflect on the predatory cultivation system; proposed the prototype of the concept of &quot;symbiosis&quot;; authored the surviving fragment of Fǎn Lüèduó Lùn (Treatise Against Predation)</td><td>The ancient pioneer of symbiotic thought; his thought, after sleeping for hundreds of millions of years, became the spiritual source of the Anchor Symbiotic Civilization</td></tr><tr><td>Wànlíng Mǔ</td><td>approx. −100 million years</td><td>Led the first large-scale experimental symbiotic civilization; although ultimately destroyed by predatory civilizations, her practice proved the feasibility of the symbiotic system</td><td>The forerunner of symbiotic practice, honored by later generations as the &quot;Mother of Symbiosis&quot;</td></tr><tr><td>Máo Jué Zhě</td><td>approx. −10,000 years</td><td>A cultivator of the First Plane who, during long-term cultivation, accidentally perceived a stable node in the law network and discovered the anchor mechanism</td><td>The discoverer of the anchor mechanism and the initiator of the Anchor Awakening Era</td></tr></tbody></table><h3 id="_2-2-founders-of-the-anchor-awakening-era" tabindex="-1">2.2 Founders of the Anchor Awakening Era <a class="header-anchor" href="#_2-2-founders-of-the-anchor-awakening-era" aria-label="Permalink to &quot;2.2 Founders of the Anchor Awakening Era&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Period</th><th>Core contributions</th><th>Historical standing</th></tr></thead><tbody><tr><td>Máo Dìng Gōng</td><td>−10,000 to −9,200 years</td><td>Disciple of Máo Jué Zhě; systematically studied the anchor mechanism; established the first artificial anchor; authored Máodiǎn Yuánlǐ (Principles of the Anchor)</td><td>The founder of anchor technology and the inventor of the artificial anchor</td></tr><tr><td>Gòngshēng Zǐ</td><td>−6,000 to −5,100 years</td><td>Combined anchor technology with symbiotic thought; founded the theoretical system of &quot;Anchor Symbiosis&quot;; authored Máodiǎn Gòngshēng Lùn (On Anchor Symbiosis)</td><td>The founder of the Anchor Symbiosis theory and the intellectual mentor of the symbiotic civilization</td></tr><tr><td>Héngyuán Gōng</td><td>−5,000 to −4,300 years</td><td>Established the first symbiotic city-state based on anchors, &quot;Héngyuan Chéng,&quot; and successfully repelled attacks from predatory civilizations</td><td>The founder of the first symbiotic city-state and a practitioner of the symbiotic system</td></tr><tr><td>Wànzú Shǐ</td><td>−2,000 to −1,200 years</td><td>Initiated the first &quot;Great Symbiosis Assembly of the Ten Thousand Races&quot;; traveled among dozens of races advocating symbiotic union</td><td>The advocate of the union of the Ten Thousand Races and a pioneer of cross-racial symbiosis</td></tr></tbody></table><h3 id="_2-3-founders-of-the-state-in-the-establishment-period-of-the-symbiotic-system" tabindex="-1">2.3 Founders of the State in the Establishment Period of the Symbiotic System <a class="header-anchor" href="#_2-3-founders-of-the-state-in-the-establishment-period-of-the-symbiotic-system" aria-label="Permalink to &quot;2.3 Founders of the State in the Establishment Period of the Symbiotic System&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Period</th><th>Core contributions</th><th>Historical standing</th></tr></thead><tbody><tr><td>Lìxiàn Gōng</td><td>−1,000 to −900 years</td><td>Chairman of the Symbiotic Constitution Drafting Committee; presided over the drafting of the Symbiotic Constitution and pushed it through the universal referendum</td><td>The principal drafter of the Symbiotic Constitution and the founding father of constitutionalism of the symbiotic civilization</td></tr><tr><td>Zhífǎ Gōng</td><td>−900 to −780 years</td><td>First chairman of the Symbiotic Executive Committee; presided over the establishment of the administrative system and legal enforcement mechanisms of the symbiotic civilization</td><td>The founder of the symbiotic administrative system and the first head of administration</td></tr><tr><td>Sīfǎ Mǔ</td><td>−900 to −800 years</td><td>First chief justice of the Symbiotic Court; established the judicial system and constitutional review system of the symbiotic civilization</td><td>The founder of the symbiotic judicial system and the first head of the judiciary</td></tr><tr><td>Sānbǎi Shī</td><td>−500 to −300 years</td><td>Presided over the excavation and compilation of the Three Hundred Origin Cultivation Systems; led the team to complete the verification of all Three Hundred Systems</td><td>The chief compiler of the Three Hundred Systems and the engineering commander-in-chief of cultivation opening</td></tr><tr><td>Bèizēng Gōng</td><td>−300 to −220 years</td><td>Presided over research on the technological application of the Multiplying Fruit; achieved the engineering breakthrough of the hundredfold deduction amplification technology</td><td>The chief scientist of the technological application of the Multiplying Fruit and a promoter of the Deduction Iteration System</td></tr></tbody></table><h3 id="_2-4-leaders-of-the-opening-and-activation-period" tabindex="-1">2.4 Leaders of the Opening and Activation Period <a class="header-anchor" href="#_2-4-leaders-of-the-opening-and-activation-period" aria-label="Permalink to &quot;2.4 Leaders of the Opening and Activation Period&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Period</th><th>Core contributions</th><th>Historical standing</th></tr></thead><tbody><tr><td>Kāifàng Gōng</td><td>−100 to −50 years</td><td>Presided over the comprehensive opening of the Three Hundred Origin Cultivation Systems; established the cultivation resource allocation system and the mentor network</td><td>The commander-in-chief of the opening of the Three Hundred Systems and a practitioner of &quot;a path for everyone&quot;</td></tr><tr><td>Jīhuó Gōng</td><td>−50 years to Year One</td><td>Presided over the implementation of the 20% Activation Strategy; led the team to complete the activation target of 20% of living beings within 50 years</td><td>The commander-in-chief of the 20% Activation Strategy and the initiator of a new era for the symbiotic civilization</td></tr><tr><td>Shēngwéi Gōng</td><td>Year One to 80</td><td>Presided over the first ascension project; promoted the implementation of the Four-Stage Ascension Path; achieved the first staged ascension</td><td>The chief engineer of the first ascension and the leader of the Ascension Era</td></tr></tbody></table><h3 id="_2-5-explorers-of-the-republic-of-ten-thousand-races-and-the-cross-plane-era" tabindex="-1">2.5 Explorers of the Republic of Ten Thousand Races and the Cross-Plane Era <a class="header-anchor" href="#_2-5-explorers-of-the-republic-of-ten-thousand-races-and-the-cross-plane-era" aria-label="Permalink to &quot;2.5 Explorers of the Republic of Ten Thousand Races and the Cross-Plane Era&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Period</th><th>Core contributions</th><th>Historical standing</th></tr></thead><tbody><tr><td>Wànzú Gòngzhǔ</td><td>100 to 200</td><td>Presided over the founding of the Republic of Ten Thousand Races; promoted the compilation of the Register of Ten Thousand Races and cross-racial integration policies</td><td>The founder of the Republic of Ten Thousand Races and the first Paramount Sovereign of the Ten Thousand Races</td></tr><tr><td>Wèimiàn Mǔ</td><td>500 to 650</td><td>First director of the Plane Administration; presided over the large-scale cross-plane exploration program; established the master database of plane coordinates</td><td>The pioneer of cross-plane exploration and the founder of the plane management system</td></tr><tr><td>Kǎogǔ Gōng</td><td>800 to 950</td><td>Presided over the final maturation of the Replication Mirror remote-site archaeology scheme; pushed cross-plane archaeology into the era of scale</td><td>The culmination of archaeological schemes and the founder of cross-plane archaeology</td></tr><tr><td>Shílǜ Gōng</td><td>1000 to 1150</td><td>Presided over the breakthrough in time regression technology; promoted the establishment of the principle of observe first, then intervene within limits</td><td>The leader of time regression technology and the framer of the time law principles</td></tr></tbody></table><h2 id="iii-important-organizations" tabindex="-1">III. Important Organizations <a class="header-anchor" href="#iii-important-organizations" aria-label="Permalink to &quot;III. Important Organizations&quot;">​</a></h2><h3 id="_3-1-supreme-power-institutions" tabindex="-1">3.1 Supreme Power Institutions <a class="header-anchor" href="#_3-1-supreme-power-institutions" aria-label="Permalink to &quot;3.1 Supreme Power Institutions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organization</th><th>Founding time</th><th>Core functions</th><th>Historical role</th></tr></thead><tbody><tr><td>Anchor Assembly</td><td>−900 years</td><td>The supreme power institution of the symbiotic civilization, composed of representatives of all races in proportion, exercising legislative power and the power to decide major matters</td><td>The supreme decision-making institution of the symbiotic civilization and the maker of all major laws and strategies</td></tr><tr><td>Symbiotic Executive Committee</td><td>−900 years</td><td>The supreme administrative institution of the symbiotic civilization, responsible for the enforcement of the constitution and laws and daily governance</td><td>The supreme administrative organ of the symbiotic civilization and the executor of laws and policies</td></tr><tr><td>Symbiotic Court</td><td>−900 years</td><td>The supreme judicial institution of the symbiotic civilization, independently exercising judicial power, responsible for constitutional review and the adjudication of major cases</td><td>The supreme judicial organ of the symbiotic civilization and the guardian of the rule of law</td></tr><tr><td>Anchor Oversight Committee</td><td>−900 years</td><td>An independent oversight institution, responsible for supervising all power institutions to prevent the abuse of power</td><td>The independent oversight organ of the symbiotic civilization and a key link in the balance of power</td></tr></tbody></table><h3 id="_3-2-specialized-management-institutions" tabindex="-1">3.2 Specialized Management Institutions <a class="header-anchor" href="#_3-2-specialized-management-institutions" aria-label="Permalink to &quot;3.2 Specialized Management Institutions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organization</th><th>Founding time</th><th>Core functions</th><th>Historical role</th></tr></thead><tbody><tr><td>Plane Administration</td><td>500</td><td>Responsible for the maintenance of the master database of plane coordinates, the approval of traversal permits, the management of cross-plane archaeology, and the coordination of cross-plane diplomacy</td><td>The competent authority for cross-plane interaction and the manager of plane exploration</td></tr><tr><td>Time Law Committee</td><td>1000</td><td>Responsible for the approval of time regression operations, time law research, and supervision of time paradox prevention and control</td><td>The approving and supervisory institution for time regression operations and the guardian of time law safety</td></tr><tr><td>Time Law Audit Committee</td><td>1050</td><td>Responsible for the post-operation audit of time regression operations, confirming that no uncontrolled timeline perturbation has been caused</td><td>The independent audit institution for time operations and the last line of defense for time regression safety</td></tr><tr><td>Cross-Plane Ethics Committee</td><td>600</td><td>Formulates and interprets cross-plane ethics guidelines, approves high-risk cross-plane interaction projects, and handles ethics violation complaints</td><td>The ethics oversight institution for cross-plane interaction and the guardian of civilizational subjectivity</td></tr><tr><td>Knowledge Return Audit Office</td><td>850</td><td>Responsible for the audit of knowledge return operations, ensuring that returned content conforms to the principle of &quot;knowledge-only retrieval&quot;</td><td>The audit institution for knowledge return and a key link in cross-plane pollution prevention</td></tr></tbody></table><h3 id="_3-3-research-and-education-institutions" tabindex="-1">3.3 Research and Education Institutions <a class="header-anchor" href="#_3-3-research-and-education-institutions" aria-label="Permalink to &quot;3.3 Research and Education Institutions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organization</th><th>Founding time</th><th>Core functions</th><th>Historical role</th></tr></thead><tbody><tr><td>Anchor Research Institute</td><td>−8,000 years</td><td>Basic research and applied development of the anchor mechanism; construction and maintenance of artificial anchors</td><td>The core research institution of anchor technology and one of the technological sources of the symbiotic civilization</td></tr><tr><td>Committee for the Compilation of the Three Hundred Systems</td><td>−500 years</td><td>Excavation, compilation, verification, and continuous optimization of the Three Hundred Origin Cultivation Systems</td><td>The compilation and maintenance institution of the Three Hundred Systems and the technical support for cultivation opening</td></tr><tr><td>Symbiotic University Alliance</td><td>−700 years</td><td>A consortium of higher education and cultivation education, responsible for advanced talent cultivation and academic research</td><td>The alliance of the highest institutions of learning of the symbiotic civilization and the core of talent cultivation and academic innovation</td></tr><tr><td>Cross-Plane Archaeology Academy</td><td>550</td><td>Cultivates professional talent in cross-plane archaeology; conducts archaeological technology research and methodological innovation</td><td>The talent cultivation and technology research and development center of cross-plane archaeology</td></tr><tr><td>Time Law Research Institute</td><td>950</td><td>Basic theoretical research on time laws and research and development of time regression technology</td><td>The core institution of time law research and the birthplace of time regression technology</td></tr></tbody></table><h3 id="_3-4-military-and-security-organizations" tabindex="-1">3.4 Military and Security Organizations <a class="header-anchor" href="#_3-4-military-and-security-organizations" aria-label="Permalink to &quot;3.4 Military and Security Organizations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organization</th><th>Founding time</th><th>Core functions</th><th>Historical role</th></tr></thead><tbody><tr><td>Symbiotic Defense Forces</td><td>−850 years</td><td>The regular defense force of the symbiotic civilization, responsible for plane defense and responses to external threats</td><td>The primary military force of the symbiotic civilization and the defender of national security</td></tr><tr><td>Plane Patrol Corps</td><td>520</td><td>Responsible for patrols and security surveillance of explored planes and responses to cross-plane security incidents</td><td>The front-line force of cross-plane security and the maintainer of plane order</td></tr><tr><td>Law Pollution Emergency Response Team</td><td>600</td><td>Responsible for emergency response to law pollution and energy pollution incidents and pollution removal</td><td>The emergency response force for law pollution and the guardian of the cosmic environment</td></tr><tr><td>Time Paradox Emergency Response Unit</td><td>1020</td><td>Responsible for emergency response to time paradox incidents and causal repair operations</td><td>The emergency response force for time paradoxes and the final guarantee of timeline stability</td></tr></tbody></table><h3 id="_3-5-civil-and-social-organizations" tabindex="-1">3.5 Civil and Social Organizations <a class="header-anchor" href="#_3-5-civil-and-social-organizations" aria-label="Permalink to &quot;3.5 Civil and Social Organizations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organization</th><th>Founding time</th><th>Core functions</th><th>Historical role</th></tr></thead><tbody><tr><td>Great Symbiosis Assembly of the Ten Thousand Races</td><td>−2,000 years</td><td>Periodic gatherings of representatives of all races to discuss cross-racial symbiosis affairs and promote cultural exchange</td><td>An important platform for exchange among all races and the predecessor organization of the Republic of Ten Thousand Races</td></tr><tr><td>Cultivators&#39; Association</td><td>−600 years</td><td>The self-governing industry organization of cultivators, responsible for protecting cultivators&#39; rights and interests and formulating industry norms</td><td>The self-governing organization of cultivators and a promoter of the standardization of the cultivation industry</td></tr><tr><td>Consumers&#39; Association</td><td>−650 years</td><td>A consumer rights protection organization, responsible for consumer rights defense, consumer education, and social supervision</td><td>The spokesperson for consumer rights and the social supervisor of market order</td></tr><tr><td>Environmental Protection Alliance</td><td>−550 years</td><td>A civil united organization for environmental protection, responsible for environmental supervision, environmental education, and ecological restoration volunteer activities</td><td>The social force of environmental protection and a promoter of the cosmic ecological civilization</td></tr><tr><td>Cross-Plane Friendship Association</td><td>580</td><td>A civil organization promoting friendly exchange between plane civilizations, responsible for civil diplomacy and cultural exchange</td><td>The core force of cross-plane civil diplomacy and a bridge of understanding between civilizations</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Key figures and organizations are the living carriers of the history of the Anchor Symbiotic Civilization. From the pioneering thinkers of antiquity to the civilization leaders of the present, from the supreme power institutions to civil social organizations, every figure and organization plays an irreplaceable role in the grand narrative of the symbiotic civilization. Their struggles and contributions together weave the magnificent epic of the Anchor Symbiotic Civilization — from nothing to existence, from small to great, from its own plane to the entire universe.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>70-纪元划分总表 (Chronology of Eras — Master Table)</li><li>49-治理框架与权力制衡 (Governance Framework and Balance of Powers)</li><li>77-万族共和成立 (The Founding of the Myriad Races Republic)</li></ul>',30)])])}const m=e(a,[["render",r]]);export{f as __pageData,m as default};
